            // SAFETY: the file is opened read-only and the map is only ever read from.
            Some(unsafe { Mmap::map(&file)? })
        };
        Ok(Self { mmap, len })
    }

    fn len(&self) -> u64 {
        self.len
    }

    fn read_range(&self, offset: u64, length: u64) -> Option<Vec<u8>> {
        let end = offset.checked_add(length)?;
        if end > self.len {
            return None;
        }
        match &self.mmap {
            Some(mmap) => Some(mmap[offset as usize..end as usize].to_vec()),
            // Empty file: only a zero-length read is in range.
            None => (length == 0).then(Vec::new),
        }
    }
}

