    /// Verify access rights and resolve the on-disk directory of `collection_name`.
    ///
    /// Returns:
    /// * [`Code::PermissionDenied`] if the caller's token is scoped to another collection,
    ///   or if (on Unix) the collection directory is a symlink escaping the storage root,
    /// * [`Code::NotFound`] if the collection does not exist on this server.
    fn resolve_collection_dir(
        &self,
        auth: &Auth,
        collection_name: &str,
    ) -> Result<PathBuf, Status> {
        // Enforce collection-level access control first.
        auth.check_collection_access(collection_name, AccessRequirements::new(), ACCESS_METHOD)
            .map_err(Status::from)?;

        let toc = self
            .dispatcher
            .toc(auth, &new_unchecked_verification_pass());
        let collections_root = toc.storage_path().join(COLLECTIONS_DIR);
        let collection_dir = collections_root.join(collection_name);

        if !collection_dir.is_dir() {
            return Err(Status::not_found(format!(
                "Collection {collection_name} does not exist"
            )));
        }

        // Make sure the collection directory itself does not escape the storage root.
        check_within(&collections_root, &collection_dir).map_err(|_| {
            Status::permission_denied(format!(
                "Collection {collection_name} resolves outside of the storage directory"
            ))
        })?;

        Ok(collection_dir)
    }

    /// Validate `rel_path` and resolve it against `collection_dir`.
    ///
    /// Rejects path traversal and (on Unix) symlink escapes.
    fn resolve_file_path(
        &self,
        collection_dir: &Path,
        rel_path: &str,
    ) -> Result<PathBuf, Status> {
        validate_relative_path(rel_path)?;
        let full_path = collection_dir.join(rel_path);
        check_within(collection_dir, &full_path).map_err(|_| {
            Status::permission_denied(format!(
                "Path '{rel_path}' resolves outside of the collection directory"
            ))
        })?;
        Ok(full_path)
    }

    /// Open the file at `rel_path` and read `length` bytes starting at `offset`.
    fn read_file_range(
        &self,
        collection_dir: &Path,
        rel_path: &str,
        offset: u64,
        length: u64,
    ) -> Result<Vec<u8>, Status> {
        let full_path = self.resolve_file_path(collection_dir, rel_path)?;
        let file = open_readable::<F>(&full_path)?;
