fn setup() -> (tempfile::TempDir, StorageReadService<MmapFile>) {
    let dir = Builder::new().prefix("stg").tempdir().unwrap();
    let coll = dir.path().join("collections").join("coll1");
    std::fs::create_dir_all(&coll).unwrap();
    std::fs::write(coll.join("file.bin"), b"hello world").unwrap();
    std::fs::write(coll.join("empty.bin"), b"").unwrap();
    std::fs::create_dir_all(coll.join("sub")).unwrap();
    std::fs::write(coll.join("sub").join("nested.txt"), b"nested").unwrap();
    let dispatcher = make_dispatcher(dir.path().to_path_buf());
    (dir, StorageReadService::new(dispatcher))
}

#[test]
fn test_file_exists() {
    let (_d, svc) = setup();
    let resp = block(svc.file_exists(tonic::Request::new(FileExistsRequest {
        collection_name: "coll1".into(),
        path: "file.bin".into(),
    })))
    .unwrap();
    assert!(resp.into_inner().exists);

    let resp = block(svc.file_exists(tonic::Request::new(FileExistsRequest {
        collection_name: "coll1".into(),
        path: "nope.bin".into(),
    })))
    .unwrap();
    assert!(!resp.into_inner().exists);
}

#[test]
fn test_length_and_read() {
    let (_d, svc) = setup();
    let len = block(svc.file_length(tonic::Request::new(FileLengthRequest {
        collection_name: "coll1".into(),
        path: "file.bin".into(),
    })))
    .unwrap()
    .into_inner()
    .length;
    assert_eq!(len, 11);

    let data = block(svc.read_bytes(tonic::Request::new(ReadBytesRequest {
        collection_name: "coll1".into(),
        path: "file.bin".into(),
        byte_offset: 6,
        length: 5,
    })))
    .unwrap()
    .into_inner()
    .data;
    assert_eq!(&data, b"world");

    let err = block(svc.read_bytes(tonic::Request::new(ReadBytesRequest {
        collection_name: "coll1".into(),
        path: "file.bin".into(),
        byte_offset: 6,
        length: 100,
    })))
    .unwrap_err();
    assert_eq!(err.code(), Code::OutOfRange);

    let err = block(svc.file_length(tonic::Request::new(FileLengthRequest {
        collection_name: "missing".into(),
        path: "file.bin".into(),
    })))
    .unwrap_err();
    assert_eq!(err.code(), Code::NotFound);
}

