#[test]
fn test_path_validation() {
    let (_d, svc) = setup();
    let err = block(svc.file_exists(tonic::Request::new(FileExistsRequest {
        collection_name: "coll1".into(),
        path: "../coll1/file.bin".into(),
    })))
    .unwrap_err();
    assert_eq!(err.code(), Code::InvalidArgument);
    assert!(err.message().contains("Invalid path component"));

    for bad in [".", "./file.bin"] {
        let err = block(svc.file_exists(tonic::Request::new(FileExistsRequest {
            collection_name: "coll1".into(),
            path: bad.into(),
        })))
        .unwrap_err();
        assert_eq!(err.code(), Code::InvalidArgument, "path {bad}");
    }
}

